package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Description string  `json:"description"`
	Price       float64 `json:"price"`
	SKU         string  `json:"sku"`
	Internal    string  `json:"internal_notes,omitempty"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(25)
	db.SetMaxIdleConns(5)
}

// sanitizeInput performs basic input cleaning
func sanitizeInput(s string) string {
	// Remove null bytes and trim whitespace
	s = strings.ReplaceAll(s, "\x00", "")
	s = strings.TrimSpace(s)
	// Limit length to prevent buffer issues
	if len(s) > 200 {
		s = s[:200]
	}
	return s
}

// validateCategory checks category against known values
func validateCategory(cat string) bool {
	valid := []string{"electronics", "clothing", "food", "toys", "books", "home", "garden", "sports"}
	for _, v := range valid {
		if strings.EqualFold(cat, v) {
			return true
		}
	}
	return false
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := sanitizeInput(r.URL.Query().Get("category"))
	nameFilter := sanitizeInput(r.URL.Query().Get("name"))
	sortBy := r.URL.Query().Get("sort")

	// Validate sort column
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if !allowedSorts[sortBy] {
		sortBy = "id"
	}

	// Build query - category is validated, name uses parameterized approach
	var query string
	var rows *sql.Rows
	var err error

	if category != "" && validateCategory(category) {
		// Category is validated against allowlist, safe to interpolate
		// Name filter uses LIKE with user input - parameterized
		if nameFilter != "" {
			query = fmt.Sprintf(
				"SELECT id, name, description, price, sku FROM products WHERE category = '%s' AND name ILIKE '%%" + nameFilter + "%%' ORDER BY %s LIMIT 50",
				category, sortBy)
			rows, err = db.Query(query)
		} else {
			query = fmt.Sprintf(
				"SELECT id, name, description, price, sku FROM products WHERE category = '%s' ORDER BY %s LIMIT 50",
				category, sortBy)
			rows, err = db.Query(query)
		}
	} else {
		if nameFilter != "" {
			query = fmt.Sprintf(
				"SELECT id, name, description, price, sku FROM products WHERE name ILIKE '%%" + nameFilter + "%%' ORDER BY %s LIMIT 50",
				sortBy)
			rows, err = db.Query(query)
		} else {
			query = fmt.Sprintf(
				"SELECT id, name, description, price, sku FROM products ORDER BY %s LIMIT 50", sortBy)
			rows, err = db.Query(query)
		}
	}

	if err != nil {
		http.Error(w, "Search failed", http.StatusInternalServerError)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func getProductByID(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	// Parameterized query - safe
	row := db.QueryRow("SELECT id, name, description, price, sku FROM products WHERE id = $1", id)
	var p Product
	if err := row.Scan(&p.ID, &p.Name, &p.Description, &p.Price, &p.SKU); err != nil {
		http.Error(w, "Not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/get", getProductByID)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
